  2	
  3	import com.fream.back.domain.m99.entity.Xkh73Status;
  4	import com.fream.back.domain.m99.entity.Xhq12;
  5	import com.fream.back.domain.m99.entity.Xtw92;
  6	import com.fream.back.domain.m99.exception.*;
  7	import com.fream.back.domain.m99.repository.Xtw92Repository;
  8	import com.fream.back.domain.m64.dto.Xjt45RequestDto;
  9	import com.fream.back.domain.m30.entity.Xcc44;
 10	import com.fream.back.domain.m30.service.p11.Xcc44QueryService;
 11	import com.fream.back.domain.m85.entity.Xpj42;
 12	import com.fream.back.domain.m85.entity.Xzt63;
 13	import com.fream.back.domain.m85.service.query.Xzt63QueryService;
 14	import com.fream.back.domain.m22.entity.Xjm45;
 15	import com.fream.back.domain.m22.service.query.Xjm45QueryService;
 16	import lombok.RequiredArgsConstructor;
 17	import lombok.extern.slf4j.Slf4j;
 18	import org.springframework.stereotype.Service;
 19	import org.springframework.transaction.annotation.Transactional;
 20	
 21	
 22	
 23	
 24	@Service
 25	@RequiredArgsConstructor
 26	@Slf4j
 27	public class Xtw92CommandService {
 28	
 29	    private final Xtw92Repository orderBidRepository;
 30	    private final Xhq12CommandService orderCommandService;
 31	    private final Xcc44QueryService productSizeQueryService;
 32	    private final Xjm45QueryService userQueryService;
 33	    private final Xzt63QueryService saleBidQueryService;
 34	
