 45	
 46	    @Transactional
 47	    public Xtw92 createOrderBid(String email, Long productSizeId, int bidPrice) {
 48	        try {
 49	
 50	            validateCreateOrderBidInput(email, productSizeId, bidPrice);
 51	
 52	
 53	            Xjm45 user = userQueryService.findByEmail(email);
 54	
 55	
 56	            Xcc44 productSize = productSizeQueryService.findById(productSizeId)
 57	                    .orElseThrow(() -> new Xpb58Exception("해당 사이즈를 찾을 수 없습니다(ID: " + productSizeId + ")"));
 58	
 59	
 60	            Xhq12 order = orderCommandService.createOrderFromBid(user, productSize, bidPrice);
 61	
 62	
 63	            Xtw92 orderBid = createAndSaveOrderBid(user, productSize, bidPrice, order);
 64	
 65	            return orderBid;
 66	        } catch (Exception e) {
 67	            handleOrderBidCreationException(e, "주문 입찰 생성");
 68	            return null;
 69	        }
 70	    }
 71	
 72	
 73	
 74	
 75	    private void validateCreateOrderBidInput(String email, Long productSizeId, int bidPrice) {
 76	        if (email == null || email.trim().isEmpty()) {
 77	            throw new Xqx49Exception("사용자 이메일이 없습니다.");
 78	        }
 79	        if (productSizeId == null) {
 80	            throw new Xpb58Exception("상품 사이즈 ID가 없습니다.");
 81	        }
 82	        if (bidPrice <= 0) {
 83	            throw new Xrs16Exception("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
 84	        }
 85	    }
 86	
 87	
 88	
 89	
 90	    private Xtw92 createAndSaveOrderBid(Xjm45 user, Xcc44 productSize, int bidPrice, Xhq12 order) {
 91	        Xtw92 orderBid = Xtw92.builder()
 92	                .user(user)
 93	                .productSize(productSize)
 94	                .bidPrice(bidPrice)
 95	                .status(Xkh73Status.PENDING)
 96	                .order(order)
 97	                .build();
 98	
 99	
100	        orderBid.assignOrder(order);
101	
102	        return orderBidRepository.save(orderBid);
103	    }
104	
105	
106	
107	
108	
109	
110	
111	
112	
113	
114	
115	
116	
117	
118	    @Transactional
119	    public Xtw92 createInstantOrderBid(String buyerEmail, Long saleBidId, Long addressId,
120	                                          boolean isWarehouseStorage, Xjt45RequestDto paymentRequest) {
121	        try {
122	
123	            validateInstantOrderBidInput(buyerEmail, saleBidId, addressId, paymentRequest);
124	
125	
126	            Xjm45 buyer = userQueryService.findByEmail(buyerEmail);
127	
128	
129	            Xzt63 saleBid = getSaleBidAndValidate(saleBidId);
130	            Xpj42 sale = saleBid.getSale();
131	
132	
133	            Xhq12 order = orderCommandService.createInstantOrder(
134	                    buyer,
135	                    saleBid,
136	                    addressId,
137	                    isWarehouseStorage,
138	                    paymentRequest
139	            );
140	
141	
142	            Xtw92 orderBid = createInstantOrderBid(order, saleBid, sale);
143	
144	            return orderBid;
145	        } catch (Exception e) {
146	            handleOrderBidCreationException(e, "즉시 구매 주문 입찰 생성");
147	            return null;
148	        }
149	    }
150	
151	
152	
153	
154	    private void validateInstantOrderBidInput(String buyerEmail, Long saleBidId, Long addressId, Xjt45RequestDto paymentRequest) {
155	        if (buyerEmail == null || buyerEmail.trim().isEmpty()) {
156	            throw new Xqx49Exception("구매자 이메일이 없습니다.");
157	        }
158	        if (saleBidId == null) {
159	            throw new Xbk76Exception("판매 입찰 ID가 없습니다.");
160	        }
161	        if (addressId == null) {
162	            throw new Xzj75Exception("배송지 ID가 없습니다.");
163	        }
164	        if (paymentRequest == null) {
165	            throw new Xtv55Exception("결제 정보가 없습니다.");
166	        }
167	    }
168	
169	
170	
171	
172	    private Xzt63 getSaleBidAndValidate(Long saleBidId) {
173	        Xzt63 saleBid = saleBidQueryService.findById(saleBidId);
174	        if (saleBid == null) {
175	            throw new Xbk76Exception("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
176	        }
177	
178	        Xpj42 sale = saleBid.getSale();
179	        if (sale == null) {
180	            throw new Xzj75Exception("판매 입찰과 연결된 판매 정보가 없습니다.");
181	        }
182	
183	        return saleBid;
184	    }
185	
186	
187	
188	
189	    private Xtw92 createInstantOrderBid(Xhq12 order, Xzt63 saleBid, Xpj42 sale) {
190	        Xcc44 productSize = saleBid.getProductSize();
191	
192	        Xtw92 orderBid = Xtw92.builder()
193	                .user(order.getUser())
194	                .productSize(productSize)
195	                .bidPrice(saleBid.getBidPrice())
196	                .status(Xkh73Status.MATCHED)
197	                .order(order)
198	                .sale(sale)
199	                .build();
200	
201	
202	        orderBid.assignOrder(order);
203	
204	
205	        orderBid.markAsInstantPurchase();
206	        return orderBidRepository.save(orderBid);
207	    }
208	
209	
210	
211	
212	    private void handleOrderBidCreationException(Exception e, String operation) {
213	        if (e instanceof Xhq12Exception) {
214	            throw (Xhq12Exception) e;
215	        }
216	        log.error("{} 중 오류 발생: {}", operation, e.getMessage(), e);
217	        throw new Xrd49Exception(operation + " 중 오류가 발생했습니다: " + e.getMessage(), e);
218	    }
219	
220	
221	
222	
223	
224	
225	
