 80	package com.fream.back.domain.m64.entity;
 82	public enum Xjt45Status {
 83	    PENDING,
 84	    PAID,
 85	    REFUND_REQUESTED,
 86	    REFUNDED,
 87	    FAILED;
 89	    public boolean canTransitionTo(Xjt45Status newStatus) {
 90	        switch (this) {
 91	            case PENDING:
 92	                return newStatus == PAID;
 93	            case PAID:
 94	                return newStatus == REFUND_REQUESTED || newStatus == REFUNDED;
 95	            case REFUND_REQUESTED:
 96	                return newStatus == REFUNDED;
 97	            default:
 98	                return false;
 99	        }
100	    }
